package kubernetes

import (
	"context"
	"errors"

	"go.etcd.io/etcd/api/v3/mvccpb"
	"go.etcd.io/etcd/client/v3"
)

var (
	// ErrNotFound is returned by Get when the requested key cannot be found.
	ErrNotFound = errors.New("kubernetes: key not found")

	// ErrRevisionConflict is returned by operations that perform optimistic
	// concurrency control when the current revision of the key does not match
	// the expected revision.
	ErrRevisionConflict = errors.New("kubernetes: revision of the key does not match the expected revision")
)

// Interface exposes a smaller set of client-side APIs which are useful
// for Kubernetes' interactions with etcd. The rationale is that Kubernetes
// does not need most of the API surface exposed by the clientv3.KV interface
// and it's easier to reason about a smaller, stable API with semantics
// tailored to Kubernetes' use cases.
//
// The keys are always returned in lexicographic order. Results of read
// operations (Get, List, Count) are linearizable by default.
type Interface interface {
	// Get gets the value of a single key.
	//
	// If the key is not found, ErrNotFound is returned. The returned response
	// contains the value and the revision of the key-value store at which the
	// read was performed. Pass GetOption.Revision to read the key as it was at
	// a specific revision.
	Get(ctx context.Context, key string, opts ...GetOption) (*GetResponse, error)

	// List returns keys in lexicographic order. The response contains the
	// matched keys, the total number of keys in the range, and the revision of
	// the key-value store at which the read was performed.
	//
	// List can be used for pagination by setting ListOption.Limit. If there
	// are more keys than the limit, the response's HasMore field is set and
	// Token contains the last key from the returned page. Pass that value as
	// ListOption.Continue in the next List call to fetch the following page.
	// Continue is interpreted as the last key of the previous page, so the
	// returned page starts with the first key strictly greater than Continue.
	// ListOption.Prefix restricts the range to keys with the given prefix.
	// ListOption.MinModRev, ListOption.MaxModRev, ListOption.MinCreateRev and
	// ListOption.MaxCreateRev filter the returned keys by their revision.
	List(ctx context.Context, opts ...ListOption) (*ListResponse, error)

	// Count returns the number of keys in a range. ListOption-like filters
	// (Prefix and revision bounds) restrict the counted range.
	Count(ctx context.Context, opts ...CountOption) (int64, error)

	// OptimisticPut writes a key-value pair, but only if the current revision
	// of the key matches expectedRevision. This allows Kubernetes to implement
	// optimistic concurrency control.
	//
	// If the current revision doesn't match expectedRevision, the key is not
	// written and ErrRevisionConflict is returned. Pass expectedRevision 0 to
	// require that the key doesn't exist; in that case the write succeeds only
	// if the key was never created or is currently deleted.
	OptimisticPut(ctx context.Context, key, value string, expectedRevision int64, opts ...PutOption) (*PutResponse, error)

	// OptimisticDelete deletes a key, but only if the current revision of the
	// key matches expectedRevision. This allows Kubernetes to implement
	// optimistic concurrency control.
	//
	// If the current revision doesn't match expectedRevision, the key is not
	// deleted and ErrRevisionConflict is returned. The operation succeeds if
	// the key exists and was last modified at expectedRevision.
	OptimisticDelete(ctx context.Context, key string, expectedRevision int64, opts ...DeleteOption) (*DeleteResponse, error)
}

// GetOption configures a Get call.
type GetOption struct {
	// Revision is the point-in-time of the key-value store to use for the read.
	// If zero, the latest revision is used.
	Revision int64
}

// ListOption configures a List call.
type ListOption struct {
	// Prefix restricts the range to keys that start with the given prefix.
	Prefix string
	// Limit bounds the number of keys returned in a single page. If zero, no
	// limit is applied.
	Limit int64
	// Revision is the point-in-time of the key-value store to use for the read.
	// If zero, the latest revision is used.
	Revision int64
	// MinModRev filters the returned keys, keeping only the keys with mod
	// revision greater or equal to the given value. Zero disables the filter.
	MinModRev int64
	// MaxModRev filters the returned keys, keeping only the keys with mod
	// revision smaller or equal to the given value. Zero disables the filter.
	MaxModRev int64
	// MinCreateRev filters the returned keys, keeping only the keys with create
	// revision greater or equal to the given value. Zero disables the filter.
	MinCreateRev int64
	// MaxCreateRev filters the returned keys, keeping only the keys with create
	// revision smaller or equal to the given value. Zero disables the filter.
	MaxCreateRev int64
	// Matcher, when set, filters the returned keys client-side. It is called
	// for every matched key-value pair and only the pairs for which it returns
	// true are included in the response.
	Matcher func([]byte, []byte) bool
	// Continue is the last key from a previous page. When set, the returned
	// page starts with the first key strictly greater than Continue. It is
	// usually the value of ListResponse.Token from a previous call.
	Continue string
}

// CountOption configures a Count call.
type CountOption struct {
	// Prefix restricts the range to keys that start with the given prefix.
	Prefix string
	// Revision is the point-in-time of the key-value store to use for the count.
	// If zero, the latest revision is used.
	Revision int64
	// MinModRev filters the counted keys, keeping only the keys with mod
	// revision greater or equal to the given value. Zero disables the filter.
	MinModRev int64
	// MaxModRev filters the counted keys, keeping only the keys with mod
	// revision smaller or equal to the given value. Zero disables the filter.
	MaxModRev int64
	// MinCreateRev filters the counted keys, keeping only the keys with create
	// revision greater or equal to the given value. Zero disables the filter.
	MinCreateRev int64
	// MaxCreateRev filters the counted keys, keeping only the keys with create
	// revision smaller or equal to the given value. Zero disables the filter.
	MaxCreateRev int64
}

// PutOption configures an OptimisticPut call.
type PutOption struct {
	// LeaseID is the lease ID to associate with the key. Zero means no lease.
	LeaseID clientv3.LeaseID
}

// DeleteOption configures an OptimisticDelete call. It is reserved for future
// extensions.
type DeleteOption struct{}

// GetResponse is the response to a Get call.
type GetResponse struct {
	// Kv is the key-value pair if the key was found.
	Kv *mvccpb.KeyValue
	// Revision is the revision of the key-value store at which the read was
	// performed.
	Revision int64
}

// ListResponse is the response to a List call.
type ListResponse struct {
	// Kvs is the list of key-value pairs matched by the call, in lexicographic
	// order.
	Kvs []*mvccpb.KeyValue
	// Count is the total number of keys in the listed range. When a limit is
	// set, Count may be larger than the number of returned keys.
	Count int64
	// Revision is the revision of the key-value store at which the read was
	// performed.
	Revision int64
	// HasMore indicates whether there are more keys beyond the returned page.
	// It is only set when a limit was used.
	HasMore bool
	// Token is set when HasMore is true and contains the last key of the
	// returned page. Pass it as ListOption.Continue in the next List call to
	// fetch the following page.
	Token string
}

// PutResponse is the response to an OptimisticPut call.
type PutResponse struct {
	// Revision is the revision of the key-value store after the write was
	// applied.
	Revision int64
}

// DeleteResponse is the response to an OptimisticDelete call.
type DeleteResponse struct {
	// Revision is the revision of the key-value store after the delete was
	// applied.
	Revision int64
}

