package kubernetes

import (
	"context"

	pb "go.etcd.io/etcd/api/v3/etcdserverpb"
	"go.etcd.io/etcd/client/v3"
)

// Client implements the kubernetes.Interface by wrapping a clientv3.Client.
type Client struct {
	*clientv3.Client
	kvClient pb.KVClient
}

var _ Interface = (*Client)(nil)

// New creates a new client from a standard etcd client config.
func New(cfg clientv3.Config) (*Client, error) {
	client, err := clientv3.New(cfg)
	if err != nil {
		return nil, err
	}
	return fromClient(client), nil
}

// FromClient creates a Client from an already established clientv3.Client.
// The returned Client shares the underlying connection, so it must not be
// used after the passed client was closed.
func FromClient(client *clientv3.Client) *Client {
	return fromClient(client)
}

func fromClient(client *clientv3.Client) *Client {
	return &Client{
		Client:   client,
		kvClient: clientv3.RetryKVClient(client),
	}
}

// Get implements the Interface.Get method.
func (c *Client) Get(ctx context.Context, key string, opts ...GetOption) (*GetResponse, error) {
	var opt GetOption
	if len(opts) > 0 {
		opt = opts[0]
	}
	resp, err := c.kvClient.Range(ctx, &pb.RangeRequest{
		Key:      []byte(key),
		Revision: opt.Revision,
	})
	if err != nil {
		return nil, clientv3.ContextError(ctx, err)
	}
	if len(resp.Kvs) == 0 {
		return nil, ErrNotFound
	}
	return &GetResponse{
		Kv:       resp.Kvs[0],
		Revision: resp.Header.Revision,
	}, nil
}

// List implements the Interface.List method.
func (c *Client) List(ctx context.Context, opts ...ListOption) (*ListResponse, error) {
	var opt ListOption
	if len(opts) > 0 {
		opt = opts[0]
	}
	key, rangeEnd := rangeBoundaries(opt.Prefix, opt.Continue)
	resp, err := c.kvClient.Range(ctx, &pb.RangeRequest{
		Key:               key,
		RangeEnd:          rangeEnd,
		Limit:             opt.Limit,
		Revision:          opt.Revision,
		MinModRevision:    opt.MinModRev,
		MaxModRevision:    opt.MaxModRev,
		MinCreateRevision: opt.MinCreateRev,
		MaxCreateRevision: opt.MaxCreateRev,
	})
	if err != nil {
		return nil, clientv3.ContextError(ctx, err)
	}
	return newListResponse(resp, opt.Matcher), nil
}

// Count implements the Interface.Count method.
func (c *Client) Count(ctx context.Context, opts ...CountOption) (int64, error) {
	var opt CountOption
	if len(opts) > 0 {
		opt = opts[0]
	}
	if opt.MinModRev != 0 || opt.MaxModRev != 0 || opt.MinCreateRev != 0 || opt.MaxCreateRev != 0 {
		// The etcd server does not apply revision filters to count requests,
		// so filter the returned keys client-side instead.
		resp, err := c.kvClient.Range(ctx, &pb.RangeRequest{
			Key:               []byte(opt.Prefix),
			RangeEnd:          prefixRangeEnd(opt.Prefix),
			Revision:          opt.Revision,
			MinModRevision:    opt.MinModRev,
			MaxModRevision:    opt.MaxModRev,
			MinCreateRevision: opt.MinCreateRev,
			MaxCreateRevision: opt.MaxCreateRev,
		})
		if err != nil {
			return 0, clientv3.ContextError(ctx, err)
		}
		var count int64
		for _, kv := range resp.Kvs {
			if kv.ModRevision < opt.MinModRev || (opt.MaxModRev != 0 && kv.ModRevision > opt.MaxModRev) {
				continue
			}
			if kv.CreateRevision < opt.MinCreateRev || (opt.MaxCreateRev != 0 && kv.CreateRevision > opt.MaxCreateRev) {
				continue
			}
			count++
		}
		return count, nil
	}
	resp, err := c.kvClient.Range(ctx, &pb.RangeRequest{
		Key:         []byte(opt.Prefix),
		RangeEnd:    prefixRangeEnd(opt.Prefix),
		CountOnly:   true,
		Revision:    opt.Revision,
	})
	if err != nil {
		return 0, clientv3.ContextError(ctx, err)
	}
	return resp.Count, nil
}

// OptimisticPut implements the Interface.OptimisticPut method.
func (c *Client) OptimisticPut(ctx context.Context, key, value string, expectedRevision int64, opts ...PutOption) (*PutResponse, error) {
	var opt PutOption
	if len(opts) > 0 {
		opt = opts[0]
	}
	tresp, err := c.kvClient.Txn(ctx, &pb.TxnRequest{
		Compare: []*pb.Compare{
			{
				Key:         []byte(key),
				Target:      pb.Compare_MOD,
				Result:      pb.Compare_EQUAL,
				TargetUnion: &pb.Compare_ModRevision{ModRevision: expectedRevision},
			},
		},
		Success: []*pb.RequestOp{
			{
				Request: &pb.RequestOp_RequestPut{
					RequestPut: &pb.PutRequest{
						Key:   []byte(key),
						Value: []byte(value),
						Lease: int64(opt.LeaseID),
					},
				},
			},
		},
	})
	if err != nil {
		return nil, clientv3.ContextError(ctx, err)
	}
	if !tresp.Succeeded {
		return nil, ErrRevisionConflict
	}
	return &PutResponse{
		Revision: tresp.Header.Revision,
	}, nil
}

// OptimisticDelete implements the Interface.OptimisticDelete method.
func (c *Client) OptimisticDelete(ctx context.Context, key string, expectedRevision int64, opts ...DeleteOption) (*DeleteResponse, error) {
	tresp, err := c.kvClient.Txn(ctx, &pb.TxnRequest{
		Compare: []*pb.Compare{
			{
				Key:         []byte(key),
				Target:      pb.Compare_MOD,
				Result:      pb.Compare_EQUAL,
				TargetUnion: &pb.Compare_ModRevision{ModRevision: expectedRevision},
			},
		},
		Success: []*pb.RequestOp{
			{
				Request: &pb.RequestOp_RequestDeleteRange{
					RequestDeleteRange: &pb.DeleteRangeRequest{
						Key: []byte(key),
					},
				},
			},
		},
	})
	if err != nil {
		return nil, clientv3.ContextError(ctx, err)
	}
	if !tresp.Succeeded {
		return nil, ErrRevisionConflict
	}
	return &DeleteResponse{
		Revision: tresp.Header.Revision,
	}, nil
}

func newListResponse(resp *pb.RangeResponse, matcher func([]byte, []byte) bool) *ListResponse {
	result := &ListResponse{
		Kvs:       resp.Kvs,
		Count:     resp.Count,
		Revision:  resp.Header.Revision,
		HasMore:   resp.More,
		Token:     "",
	}
	if matcher != nil {
		matched := make([]*mvccpb.KeyValue, 0, len(resp.Kvs))
		for _, kv := range resp.Kvs {
			if matcher(kv.Key, kv.Value) {
				matched = append(matched, kv)
			}
		}
		result.Kvs = matched
	}
	if result.HasMore && len(result.Kvs) > 0 {
		result.Token = string(result.Kvs[len(result.Kvs)-1].Key)
	}
	return result
}

// rangeBoundaries computes the [key, rangeEnd) boundaries used by List.
// Continue is interpreted as the last key of a previous page, so the range
// starts with the first key strictly greater than it.
func rangeBoundaries(prefix, continueKey string) (key, rangeEnd []byte) {
	if continueKey != "" {
		key = []byte(continueKey + "\x00")
	} else {
		key = []byte(prefix)
	}
	return key, prefixRangeEnd(prefix)
}

func prefixRangeEnd(prefix string) []byte {
	if prefix == "" {
		return nil
	}
	return []byte(clientv3.GetPrefixRangeEnd(prefix))
}

