func newListResponse(resp *pb.RangeResponse, matcher func([]byte, []byte) bool) *ListResponse {
	result := &ListResponse{
		Kvs:      resp.Kvs,
		Count:    resp.Count,
		Revision: resp.Header.Revision,
		HasMore:  resp.More,
		Token:    "",
	}
	if matcher != nil {
		matched := make([]*mvccpb.KeyValue, 0, len(resp.Kvs))
		for _, kv := range resp.Kvs {
			if matcher(kv.Key, kv.Value) {
				matched = append(matched, kv)
			}
		}
		result.Kvs = matched
	}
	if result.HasMore && len(result.Kvs) > 0 {
		result.Token = string(result.Kvs[len(result.Kvs)-1].Key)
	}
	return result
}

// rangeBoundaries computes the [key, rangeEnd) boundaries used by List.
// Continue is interpreted as the last key of a previous page, so the range
// starts with the first key strictly greater than it.
//
// The range end "\x00" is the special "from key" marker recognized by etcd,
// meaning all keys greater or equal to the range start.
func rangeBoundaries(prefix, continueKey string) (key, rangeEnd []byte) {
	key, rangeEnd = prefixRange(prefix)
	if continueKey != "" {
		// Continue is the last key of a previously returned page. Appending
		// "\x00" gives the immediate successor of that key, so the returned
		// page starts with the first key strictly greater than Continue.
		key = []byte(continueKey + "\x00")
	}
	return key, rangeEnd
}

func prefixRange(prefix string) (key, end []byte) {
	if prefix == "" {
		// List all keys: "\x00" is the first possible key and at the same
		// time the special "from key" range end marker.
		return []byte{0}, []byte{0}
	}
	return []byte(prefix), []byte(clientv3.GetPrefixRangeEnd(prefix))
}

