func newTestClient(kvClient pb.KVClient) *Client {
	return &Client{kvClient: kvClient}
}

func TestNew(t *testing.T) {
	// A misconfigured call limit is rejected before any connection is made.
	_, err := New(clientv3.Config{
		Endpoints:          []string{"http://localhost:1"},
		MaxCallSendMsgSize: 1000,
		MaxCallRecvMsgSize: 2000,
	})
	if err == nil {
		t.Fatal("New() expected an error for inconsistent config, got nil")
	}
}

func TestFromClient(t *testing.T) {
	client, err := clientv3.New(clientv3.Config{Endpoints: []string{"http://localhost:1"}})
	if err != nil {
		t.Fatalf("failed to create client: %v", err)
	}
	c := FromClient(client)
	if c == nil {
		t.Fatal("FromClient() returned nil")
	}
	if c.Client != client {
		t.Errorf("FromClient() did not wrap the given clientv3.Client")
	}
	if c.kvClient == nil {
		t.Error("FromClient() did not initialize the KV client")
	}
	var _ Interface = c
	client.Close()
}

func TestGet(t *testing.T) {
	kv := &mvccpb.KeyValue{Key: []byte("foo"), Value: []byte("bar"), ModRevision: 2}
	kvClient := &fakeKVClient{
		rangeFunc: func(ctx context.Context, in *pb.RangeRequest, opts ...grpc.CallOption) (*pb.RangeResponse, error) {
			if string(in.Key) != "foo" {
				t.Errorf("unexpected key %q", string(in.Key))
			}
			if in.Revision != 5 {
				t.Errorf("expected revision 5, got %d", in.Revision)
			}
			return &pb.RangeResponse{Kvs: []*mvccpb.KeyValue{kv}, Header: &pb.ResponseHeader{Revision: 6}}, nil
		},
	}
	c := newTestClient(kvClient)
	resp, err := c.Get(context.Background(), "foo", GetOption{Revision: 5})
	if err != nil {
		t.Fatalf("Get() failed: %v", err)
	}
	if resp.Kv != kv {
		t.Errorf("unexpected kv returned: %+v", resp.Kv)
	}
	if resp.Revision != 6 {
		t.Errorf("expected revision 6, got %d", resp.Revision)
	}
}

