func TestList(t *testing.T) {
	kvClient := &fakeKVClient{
		rangeFunc: func(ctx context.Context, in *pb.RangeRequest, opts ...grpc.CallOption) (*pb.RangeResponse, error) {
			if string(in.Key) != "a/" {
				t.Errorf("unexpected key %q", string(in.Key))
			}
			if string(in.RangeEnd) != "a0" {
				t.Errorf("unexpected range end %q", string(in.RangeEnd))
			}
			if in.Limit != 2 {
				t.Errorf("expected limit 2, got %d", in.Limit)
			}
			return &pb.RangeResponse{
				Kvs: []*mvccpb.KeyValue{
					{Key: []byte("a/1"), Value: []byte("1")},
					{Key: []byte("a/2"), Value: []byte("2")},
					{Key: []byte("a/3"), Value: []byte("3")},
				}[:2],
				Count:  3,
				More:   true,
				Header: &pb.ResponseHeader{Revision: 7},
			}, nil
		},
	}
	c := newTestClient(kvClient)
	resp, err := c.List(context.Background(), ListOption{Prefix: "a/", Limit: 2})
	if err != nil {
		t.Fatalf("List() failed: %v", err)
	}
	if len(resp.Kvs) != 2 {
		t.Fatalf("expected 2 kvs, got %d", len(resp.Kvs))
	}
	if resp.Count != 3 {
		t.Errorf("expected count 3, got %d", resp.Count)
	}
	if resp.Revision != 7 {
		t.Errorf("expected revision 7, got %d", resp.Revision)
	}
	if !resp.HasMore {
		t.Error("expected HasMore to be true")
	}
	if resp.Token != "a/2" {
		t.Errorf("expected token \"a/2\", got %q", resp.Token)
	}
}

func TestListContinue(t *testing.T) {
	kvClient := &fakeKVClient{
		rangeFunc: func(ctx context.Context, in *pb.RangeRequest, opts ...grpc.CallOption) (*pb.RangeResponse, error) {
			// The next page must start with the immediate successor of the
			// last returned key and stay within the prefix range.
			if string(in.Key) != "a/2\x00" {
				t.Errorf("unexpected continuation key %q", string(in.Key))
			}
			if string(in.RangeEnd) != "a0" {
				t.Errorf("unexpected range end %q", string(in.RangeEnd))
			}
			return &pb.RangeResponse{
				Kvs:    []*mvccpb.KeyValue{{Key: []byte("a/3"), Value: []byte("3")}},
				Count:  3,
				Header: &pb.ResponseHeader{Revision: 7},
			}, nil
		},
	}
	c := newTestClient(kvClient)
	resp, err := c.List(context.Background(), ListOption{Prefix: "a/", Continue: "a/2"})
	if err != nil {
		t.Fatalf("List() failed: %v", err)
	}
	if len(resp.Kvs) != 1 || string(resp.Kvs[0].Key) != "a/3" {
		t.Errorf("unexpected kvs: %+v", resp.Kvs)
	}
}

func TestListMatcher(t *testing.T) {
	kvClient := &fakeKVClient{
		rangeFunc: func(ctx context.Context, in *pb.RangeRequest, opts ...grpc.CallOption) (*pb.RangeResponse, error) {
			return &pb.RangeResponse{
				Kvs: []*mvccpb.KeyValue{
					{Key: []byte("a/1"), Value: []byte("x")},
					{Key: []byte("a/2"), Value: []byte("y")},
				},
				Count:  2,
				Header: &pb.ResponseHeader{Revision: 1},
			}, nil
		},
	}
	c := newTestClient(kvClient)
	matcher := func(key, value []byte) bool { return string(value) == "y" }
	resp, err := c.List(context.Background(), ListOption{Prefix: "a/", Matcher: matcher})
	if err != nil {
		t.Fatalf("List() failed: %v", err)
	}
	if len(resp.Kvs) != 1 || string(resp.Kvs[0].Key) != "a/2" {
		t.Errorf("expected only matching kv, got %+v", resp.Kvs)
	}
}

