func TestOptimisticPut(t *testing.T) {
	kvClient := &fakeKVClient{
		txnFunc: func(ctx context.Context, in *pb.TxnRequest, opts ...grpc.CallOption) (*pb.TxnResponse, error) {
			if len(in.Compare) != 1 {
				t.Fatalf("expected 1 compare, got %d", len(in.Compare))
			}
			cmp := in.Compare[0]
			if string(cmp.Key) != "foo" {
				t.Errorf("unexpected compare key %q", string(cmp.Key))
			}
			if cmp.Result != pb.Compare_EQUAL || cmp.Target != pb.Compare_MOD {
				t.Errorf("expected MOD EQUAL compare, got %+v", cmp)
			}
			modRev, ok := cmp.TargetUnion.(*pb.Compare_ModRevision)
			if !ok || modRev.ModRevision != 3 {
				t.Errorf("expected expectedRevision 3, got %+v", cmp.TargetUnion)
			}
			if len(in.Success) != 1 {
				t.Fatalf("expected 1 success op, got %d", len(in.Success))
			}
			put, ok := in.Success[0].Request.(*pb.RequestOp_RequestPut)
			if !ok || string(put.RequestPut.Value) != "bar" {
				t.Fatalf("expected put op with value \"bar\", got %+v", in.Success[0].Request)
			}
			return &pb.TxnResponse{Succeeded: true, Header: &pb.ResponseHeader{Revision: 4}}, nil
		},
	}
	c := newTestClient(kvClient)
	resp, err := c.OptimisticPut(context.Background(), "foo", "bar", 3)
	if err != nil {
		t.Fatalf("OptimisticPut() failed: %v", err)
	}
	if resp.Revision != 4 {
		t.Errorf("expected revision 4, got %d", resp.Revision)
	}
}

