func TestRangeBoundaries(t *testing.T) {
	tests := []struct {
		name       string
		prefix     string
		continueKV string
		wantKey    string
		wantEnd    string
	}{
		{name: "empty", wantKey: "\x00", wantEnd: "\x00"},
		{name: "prefix", prefix: "a/", wantKey: "a/", wantEnd: "a0"},
		{name: "continue", prefix: "a/", continueKV: "a/2", wantKey: "a/2\x00", wantEnd: "a0"},
		{name: "continue without prefix", continueKV: "key", wantKey: "key\x00", wantEnd: "\x00"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			key, end := rangeBoundaries(tt.prefix, tt.continueKV)
			if string(key) != tt.wantKey {
				t.Errorf("expected key %q, got %q", tt.wantKey, string(key))
			}
			if string(end) != tt.wantEnd {
				t.Errorf("expected range end %q, got %q", tt.wantEnd, string(end))
			}
		})
	}
}

