		Kvs:    kvs,
		Count:  3,
		More:   true,
		Header: &pb.ResponseHeader{Revision: 4},
	}, nil)
	if resp.Count != 3 {
		t.Errorf("expected count 3, got %d", resp.Count)
	}
	if resp.Revision != 4 {
		t.Errorf("expected revision 4, got %d", resp.Revision)
	}
	if !resp.HasMore {
