func TestContextError(t *testing.T) {
	// A cancellation triggered through the passed in context is surfaced as
	// the context's own error.
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	err := clientv3.ContextError(ctx, context.Canceled)
	if !errors.Is(err, context.Canceled) {
		t.Errorf("expected context error to be preserved, got %v", err)
	}
	if err := clientv3.ContextError(context.Background(), nil); err != nil {
		t.Errorf("expected nil error, got %v", err)
	}
}

