// Package report provides helpers to collect and persist robustness test
// results, including loading of requests persisted in the etcd WAL files.
package report

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/google/go-cmp/cmp"
	"go.uber.org/zap"

	pb "go.etcd.io/etcd/api/v3/etcdserverpb"
	"go.etcd.io/etcd/pkg/v3/pbutil"
	"go.etcd.io/etcd/raft/v3/raftpb"
	"go.etcd.io/etcd/server/v3/storage/datadir"
	"go.etcd.io/etcd/server/v3/storage/wal"
	"go.etcd.io/etcd/server/v3/storage/wal/walpb"
	"go.etcd.io/etcd/tests/v3/framework/e2e"
	"go.etcd.io/etcd/tests/v3/robustness/model"
)

// LoadClusterPersistedRequests loads the requests persisted in the WAL files
// of all members saved under the provided test results path. Member data
// directories are expected to be prefixed with "server-".
func LoadClusterPersistedRequests(lg *zap.Logger, path string) ([]model.EtcdRequest, error) {
	files, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	dataDirs := []string{}
	for _, file := range files {
		if file.IsDir() && strings.HasPrefix(file.Name(), "server-") {
			dataDirs = append(dataDirs, filepath.Join(path, file.Name()))
		}
	}
	return PersistedRequestsDirs(lg, dataDirs)
}

// PersistedRequestsCluster loads the requests persisted in the WAL files of
// all the etcd members in the cluster.
func PersistedRequestsCluster(lg *zap.Logger, cluster *e2e.EtcdProcessCluster) ([]model.EtcdRequest, error) {
	dataDirs := []string{}
	for _, proc := range cluster.Procs {
		dataDirs = append(dataDirs, proc.Config().DataDirPath)
	}
	return PersistedRequestsDirs(lg, dataDirs)
}

// PersistedRequestsDirs loads the requests persisted in the WAL files of the
// provided data directories and merges them into a single list ordered by the
// raft log index. The failures of reading the WAL of a minority of the members
// are tolerated.
func PersistedRequestsDirs(lg *zap.Logger, dataDirs []string) ([]model.EtcdRequest, error) {
	persistedRequests := []model.EtcdRequest{}
	// Allow failure in minority of etcd cluster.
	// 0 failures in 1 node cluster, 1 failure in 3 node cluster.
	allowedFailures := len(dataDirs) / 2
	for _, dir := range dataDirs {
		memberRequests, err := requestsPersistedInWAL(lg, dir)
		if err != nil {
			if allowedFailures < 1 {
				return nil, err
			}
			allowedFailures--
			continue
		}
		minLength := min(len(persistedRequests), len(memberRequests))
		if diff := cmp.Diff(memberRequests[:minLength], persistedRequests[:minLength]); diff != "" {
			return nil, fmt.Errorf("unexpected differences between wal entries, diff:\n%s", diff)
		}
		if len(memberRequests) > len(persistedRequests) {
			persistedRequests = memberRequests
		}
	}
	return persistedRequests, nil
}

func requestsPersistedInWAL(lg *zap.Logger, dataDir string) ([]model.EtcdRequest, error) {
	_, ents, err := ReadWAL(lg, dataDir)
	if err != nil {
		return nil, err
	}
	requests := make([]model.EtcdRequest, 0, len(ents))
	for _, ent := range ents {
		if ent.Type != raftpb.EntryNormal || len(ent.Data) == 0 {
			continue
		}
		request, err := parseEntryNormal(ent)
		if err != nil {
			return nil, err
		}
		if request != nil {
			requests = append(requests, *request)
		}
	}
	return requests, nil
}

// ReadWAL reads all the entries from the WAL stored in the provided member
// data directory. Entries that were overridden by newer ones (e.g. due to a
// leader change) are suppressed and truncated entries are repaired, if
// possible.
func ReadWAL(lg *zap.Logger, dataDir string) (state raftpb.HardState, ents []raftpb.Entry, err error) {
	walDir := datadir.ToWALDir(dataDir)
	repaired := false
	for {
		w, err := wal.OpenForRead(lg, walDir, walpb.Snapshot{Index: 0})
		if err != nil {
			return state, nil, fmt.Errorf("failed to open WAL, err: %v", err)
		}
		_, state, ents, err = w.ReadAll()
		w.Close()
		if err != nil {
			if errors.Is(err, wal.ErrSnapshotNotFound) {
				return state, ents, nil
			}
			// we can only repair ErrUnexpectedEOF and we never repair twice.
			if repaired || !errors.Is(err, io.ErrUnexpectedEOF) {
				return state, nil, fmt.Errorf("failed to read WAL, cannot be repaired, err: %v", err)
			}
			if !wal.Repair(lg, walDir) {
				return state, nil, fmt.Errorf("failed to repair WAL, err: %v", err)
			}
			lg.Info("repaired WAL", zap.Error(err))
			repaired = true
			continue
		}
		return state, ents, nil
	}
}

func parseEntryNormal(ent raftpb.Entry) (*model.EtcdRequest, error) {
	var raftReq pb.InternalRaftRequest
	if err := raftReq.Unmarshal(ent.Data); err != nil {
		var r pb.Request
		if isV2Entry := pbutil.MaybeUnmarshal(&r, ent.Data); isV2Entry {
			// Legacy v2 request, ignore.
			return nil, nil
		}
		return nil, err
	}
	if raftReq.V2 != nil {
		// v2 request wrapped in an internal raft request, ignore.
		return nil, nil
	}
	switch {
	case raftReq.Put != nil:
		op := model.EtcdOperation{
			Type:    model.Put,
			Key:     string(raftReq.Put.Key),
			Value:   model.ToValueOrHash(string(raftReq.Put.Value)),
			LeaseID: raftReq.Put.Lease,
		}
		request := model.EtcdRequest{
			Type: model.Txn,
			Txn:  &model.TxnRequest{Ops: []model.EtcdOperation{op}},
		}
		return &request, nil
	case raftReq.DeleteRange != nil:
		op := model.EtcdOperation{Type: model.Delete, Key: string(raftReq.DeleteRange.Key)}
		request := model.EtcdRequest{
			Type: model.Txn,
			Txn:  &model.TxnRequest{Ops: []model.EtcdOperation{op}},
		}
		return &request, nil
	case raftReq.LeaseGrant != nil:
		return &model.EtcdRequest{
			Type:       model.LeaseGrant,
			LeaseGrant: &model.LeaseGrantRequest{LeaseID: raftReq.LeaseGrant.ID},
		}, nil
	case raftReq.LeaseRevoke != nil:
		return &model.EtcdRequest{
			Type:        model.LeaseRevoke,
			LeaseRevoke: &model.LeaseRevokeRequest{LeaseID: raftReq.LeaseRevoke.ID},
		}, nil
	case raftReq.Txn != nil:
		txn := model.TxnRequest{}
		for _, cmp := range raftReq.Txn.Compare {
			switch {
			case cmp.Result == pb.Compare_EQUAL && cmp.Target == pb.Compare_VALUE:
				txn.Conds = append(txn.Conds, model.EtcdCondition{
					Key:           string(cmp.Key),
					ExpectedValue: model.ToValueOrHash(string(cmp.Value)),
				})
			default:
				// Unsupported condition, skip it.
			}
		}
		for _, op := range raftReq.Txn.Success {
			txn.Ops = append(txn.Ops, toEtcdOperation(op))
		}
		request := model.EtcdRequest{
			Type: model.Txn,
			Txn:  &txn,
		}
		return &request, nil
	case raftReq.Compaction != nil, raftReq.ClusterVersionSet != nil, raftReq.ClusterMemberAttrSet != nil, raftReq.DowngradeInfoSet != nil:
		// Ignore internal requests.
		return nil, nil
	default:
		return nil, nil
	}
}

func toEtcdOperation(op *pb.RequestOp) (operation model.EtcdOperation) {
	switch {
	case op.GetRequestRange() != nil:
		rangeOp := op.GetRequestRange()
		operation = model.EtcdOperation{
			Type: model.Get,
			Key:  string(rangeOp.Key),
		}
	case op.GetRequestPut() != nil:
		putOp := op.GetRequestPut()
		operation = model.EtcdOperation{
			Type:    model.Put,
			Key:     string(putOp.Key),
			Value:   model.ToValueOrHash(string(putOp.Value)),
			LeaseID: putOp.Lease,
		}
	case op.GetRequestDeleteRange() != nil:
		deleteOp := op.GetRequestDeleteRange()
		operation = model.EtcdOperation{
			Type: model.Delete,
			Key:  string(deleteOp.Key),
		}
	default:
		panic(fmt.Sprintf("Unknown op type %v", op.GetType()))
	}
	return operation
}

func min(x, y int) int {
	if x < y {
		return x
	}
	return y
}

