package validate

import (
	"fmt"

	"github.com/anishathalye/porcupine"

	"go.etcd.io/etcd/tests/v3/robustness/model"
)

// PatchedOperationHistory patches the operation history. Successful operations
// are left as they are. Failed operations are patched using the watch events
// and the requests persisted in the WAL, setting a more accurate return time,
// and removing persisted requests that were not persisted.
func PatchedOperationHistory(operations []porcupine.Operation, watchEvents []WatchEvent, persistedRequests []model.EtcdRequest) []porcupine.Operation {
	uniqueEvents := uniqueWatchEvents(watchEvents)
	operationsReturnTime := persistedOperationsReturnTime(operations, persistedRequests)
	return patchOperations(operations, uniqueEvents, operationsReturnTime)
}

func uniqueWatchEvents(events []WatchEvent) map[model.EtcdOperation]WatchEvent {
	uniqueEvents := map[model.EtcdOperation]WatchEvent{}
	for _, event := range events {
		uniqueEvents[event.Op] = event
	}
	return uniqueEvents
}

func patchOperations(operations []porcupine.Operation, watchEvents map[model.EtcdOperation]WatchEvent, persistedOperations map[model.EtcdOperation]int64) []porcupine.Operation {
	newOperations := make([]porcupine.Operation, 0, len(operations))
	lastObservedOperation := lastOperationObservedInWatch(operations, watchEvents)

	for _, op := range operations {
		request := op.Input.(model.EtcdRequest)
		resp := op.Output.(model.EtcdResponse)
		if resp.Err == nil || request.Type != model.Txn {
			// Cannot patch those requests.
			newOperations = append(newOperations, op)
			continue
		}
		if op.Call <= lastObservedOperation.Call {
			matchingEvent := matchWatchEvent(request.Txn, watchEvents)
			if matchingEvent != nil {
				eventTime := matchingEvent.Time.UnixNano()
				// Set revision and time based on watchEvent.
				if eventTime < op.Return {
					op.Return = eventTime
				}
				op.Output = model.EtcdResponse{
					Revision:      matchingEvent.Revision,
					ResultUnknown: true,
				}
			}
		}
		persistedReturnTime := matchReturnTime(request, persistedOperations)
		if persistedReturnTime != nil {
			// Set return time based on persisted return time.
			if *persistedReturnTime < op.Return {
				op.Return = *persistedReturnTime
			}
		}
		if persistedReturnTime == nil && canBeDiscarded(request.Txn) {
			// Remove non persisted operations.
			continue
		}
		// Leave operation as it is as we cannot discard it.
		newOperations = append(newOperations, op)
	}
	return newOperations
}

func lastOperationObservedInWatch(operations []porcupine.Operation, watchEvents map[model.EtcdOperation]WatchEvent) porcupine.Operation {
	var maxCallTime int64
	var lastOperation porcupine.Operation
	for _, op := range operations {
		request := op.Input.(model.EtcdRequest)
		if request.Type != model.Txn {
			continue
		}
		event := matchWatchEvent(request.Txn, watchEvents)
		if event != nil && op.Call > maxCallTime {
			maxCallTime = op.Call
			lastOperation = op
		}
	}
	return lastOperation
}

func matchWatchEvent(request *model.TxnRequest, watchEvents map[model.EtcdOperation]WatchEvent) *WatchEvent {
	for _, etcdOp := range request.Ops {
		if etcdOp.Type == model.Put {
			// Remove LeaseID which is not exposed in watch.
			event, ok := watchEvents[model.EtcdOperation{
				Type:  etcdOp.Type,
				Key:   etcdOp.Key,
				Value: etcdOp.Value,
			}]
			if ok {
				return &event
			}
		}
	}
	return nil
}

// canBeDiscarded checks if a failed operation can be removed from the history
// when it was not persisted. Only operations containing a unique write or no
// writes at all can be discarded, as they can be reliably recreated by the
// model.
func canBeDiscarded(request *model.TxnRequest) bool {
	return hasUniqueWriteOperation(request.Ops) || !hasNonUniqueWriteOperation(request.Ops)
}

func hasNonUniqueWriteOperation(request *model.TxnRequest) bool {
	for _, etcdOp := range request.Ops {
		if etcdOp.Type == model.Put || etcdOp.Type == model.Delete {
			return true
		}
	}
	return false
}

func hasUniqueWriteOperation(request *model.TxnRequest) bool {
	for _, etcdOp := range request.Ops {
		if etcdOp.Type == model.Put {
			return true
		}
	}
	return false
}

// persistedOperationsReturnTime computes the return time of the operations
// persisted in the WAL based on the persisted requests and the return times of
// the observed operations.
func persistedOperationsReturnTime(allOperations []porcupine.Operation, persistedRequests []model.EtcdRequest) map[model.EtcdOperation]int64 {
	operationReturnTime := operationReturnTime(allOperations)
	persisted := map[model.EtcdOperation]int64{}

	lastReturnTime := maxReturnTime(operationReturnTime)

	for i := len(persistedRequests) - 1; i >= 0; i-- {
		request := persistedRequests[i]
		switch request.Type {
		case model.Txn:
			hasPut := false
			lastReturnTime--
			for _, op := range request.Txn.Ops {
				if op.Type != model.Put {
					continue
				}
				if _, found := persisted[op]; found {
					panic(fmt.Sprintf("Unexpected duplicate event in persisted requests. %d %+v", i, op))
				}
				hasPut = true
				persisted[op] = lastReturnTime
			}
			if hasPut {
				newReturnTime := requestReturnTime(operationReturnTime, request)
				if newReturnTime != -1 {
					lastReturnTime = min(lastReturnTime, newReturnTime)
				}
			}
		case model.LeaseGrant, model.LeaseRevoke, model.Defragment:
			// No return time is patched for non-transactional requests.
		default:
			panic(fmt.Sprintf("Unknown request type: %q", request.Type))
		}
	}
	return persisted
}

func operationReturnTime(operations []porcupine.Operation) map[model.EtcdOperation]int64 {
	newOperations := map[model.EtcdOperation]int64{}
	for _, op := range operations {
		request := op.Input.(model.EtcdRequest)
		switch request.Type {
		case model.Txn:
			for _, etcdOp := range request.Txn.Ops {
				if etcdOp.Type != model.Put {
					continue
				}
				if _, found := newOperations[etcdOp]; found {
					panic("Unexpected duplicate event in persisted requests.")
				}
				newOperations[etcdOp] = op.Return
			}
		case model.LeaseGrant, model.LeaseRevoke, model.Defragment:
			// No return time is patched for non-transactional requests.
		default:
			panic(fmt.Sprintf("Unknown request type: %q", request.Type))
		}
	}
	return newOperations
}

func maxReturnTime(operationTime map[model.EtcdOperation]int64) int64 {
	var maxReturnTime int64
	for _, returnTime := range operationTime {
		if returnTime > maxReturnTime {
			maxReturnTime = returnTime
		}
	}
	return maxReturnTime
}

func requestReturnTime(operationTime map[model.EtcdOperation]int64, request model.EtcdRequest) int64 {
	switch request.Type {
	case model.Txn:
		for _, op := range request.Txn.Ops {
			if op.Type != model.Put {
				continue
			}
			if time, found := operationTime[op]; found {
				return time
			}
		}
		return -1
	default:
		panic(fmt.Sprintf("Unknown request type: %q", request.Type))
	}
}

func matchReturnTime(request model.EtcdRequest, persistedOperations map[model.EtcdOperation]int64) *int64 {
	for _, etcdOp := range request.Txn.Ops {
		if etcdOp.Type != model.Put {
			continue
		}
		if returnTime, found := persistedOperations[etcdOp]; found {
			return &returnTime
		}
	}
	return nil
}

func min(x, y int64) int64 {
	if x < y {
		return x
	}
	return y
}

