func TestLoadClusterPersistedRequests(t *testing.T) {
	testdataPath := t.TempDir()
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"), testRequests()...)
	createMemberWAL(t, filepath.Join(testdataPath, "server-1"), testRequests()...)

	lg := zaptest.NewLogger(t)
	requests, err := LoadClusterPersistedRequests(lg, testdataPath)
	if err != nil {
		t.Fatalf("Failed to load persisted requests: %v", err)
	}
	got := memberRequests(t, lg, filepath.Join(testdataPath, "server-0"))
	if len(requests) != len(got) {
		t.Fatalf("Unexpected number of requests, got: %d, want: %d", len(requests), len(got))
	}
	for i := range requests {
		if diff := modelDiff(requests[i], got[i]); diff != "" {
			t.Errorf("Unexpected request on position %d, diff:\n%s", i, diff)
		}
	}
}

func TestPersistedRequestsDirsSingleNode(t *testing.T) {
	testdataPath := t.TempDir()
	expected := testRequests()
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"), expected...)

	lg := zaptest.NewLogger(t)
	requests, err := PersistedRequestsDirs(lg, []string{filepath.Join(testdataPath, "server-0")})
	if err != nil {
		t.Fatalf("Failed to load persisted requests: %v", err)
	}
	if len(requests) != len(expected) {
		t.Fatalf("Unexpected number of requests, got: %d, want: %d", len(requests), len(expected))
	}
	for i := range requests {
		if diff := modelDiff(requests[i], expected[i]); diff != "" {
			t.Errorf("Unexpected request on position %d, diff:\n%s", i, diff)
		}
	}
}

func TestPersistedRequestsDirsAllowsMinorityFailure(t *testing.T) {
	testdataPath := t.TempDir()
	expected := testRequests()
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"), expected...)
	// server-1 has no WAL, reading it should fail but be tolerated.
	createMemberDataDir(t, filepath.Join(testdataPath, "server-1"))

	lg := zaptest.NewLogger(t)
	requests, err := PersistedRequestsDirs(lg, []string{
		filepath.Join(testdataPath, "server-0"),
		filepath.Join(testdataPath, "server-1"),
	})
	if err != nil {
		t.Fatalf("Minority failure should be tolerated, err: %v", err)
	}
	if len(requests) != len(expected) {
		t.Fatalf("Unexpected number of requests, got: %d, want: %d", len(requests), len(expected))
	}
}

func TestPersistedRequestsDirsFailsOnMajorityFailure(t *testing.T) {
	testdataPath := t.TempDir()
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"), testRequests()...)
	// server-1 has no WAL, reading it should fail and not be tolerated
	// as this is the only other member.
	createMemberDataDir(t, filepath.Join(testdataPath, "server-1"))

	lg := zaptest.NewLogger(t)
	requests, err := PersistedRequestsDirs(lg, []string{
		filepath.Join(testdataPath, "server-1"),
		filepath.Join(testdataPath, "server-0"),
	})
	if err != nil {
		t.Fatalf("Minority failure should be tolerated, err: %v", err)
	}
	if len(requests) != len(testRequests()) {
		t.Fatalf("Unexpected number of requests, got: %d, want: %d", len(requests), len(testRequests()))
	}
}

func TestPersistedRequestsDirsConflictingEntries(t *testing.T) {
	testdataPath := t.TempDir()
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"), testRequests()...)
	conflicting := testRequests()
	conflicting[0] = model.EtcdRequest{
		Type: model.Txn,
		Txn: &model.TxnRequest{Ops: []model.EtcdOperation{{
			Type:  model.Put,
			Key:   "conflicting",
			Value: model.ToValueOrHash("value"),
		}}},
	}
	createMemberWAL(t, filepath.Join(testdataPath, "server-1"), conflicting...)

	lg := zaptest.NewLogger(t)
	_, err := PersistedRequestsDirs(lg, []string{
		filepath.Join(testdataPath, "server-0"),
		filepath.Join(testdataPath, "server-1"),
	})
	if err == nil {
		t.Fatalf("Expected error for conflicting WAL entries")
	}
}

func memberRequests(t *testing.T, lg *zap.Logger, dataDir string) []model.EtcdRequest {
	t.Helper()
	requests, err := requestsPersistedInWAL(lg, dataDir)
	if err != nil {
		t.Fatalf("Failed to read WAL: %v", err)
	}
	return requests
}

func testRequests() []model.EtcdRequest {
	return []model.EtcdRequest{
		{
			Type: model.Txn,
			Txn: &model.TxnRequest{Ops: []model.EtcdOperation{{
				Type:  model.Put,
				Key:   "key-1",
				Value: model.ToValueOrHash("value-1"),
			}}},
		},
