			Type:       model.LeaseGrant,
			LeaseGrant: &model.LeaseGrantRequest{LeaseID: 123},
		},
		{
			Type: model.Txn,
			Txn: &model.TxnRequest{
				Conds: []model.EtcdCondition{{
					Key:           "key-c",
					ExpectedValue: model.ToValueOrHash("value-c"),
				}},
				Ops: []model.EtcdOperation{
					{
						Type:  model.Put,
						Key:   "key-3",
						Value: model.ToValueOrHash("value-3"),
