func createMemberDataDir(t *testing.T, dataDir string) {
	t.Helper()
	if err := os.MkdirAll(dataDir, 0755); err != nil {
		t.Fatal(err)
	}
}

// createMemberWAL creates a member data directory with a WAL containing the
// given requests.
func createMemberWAL(t *testing.T, dataDir string, requests ...model.EtcdRequest) {
	t.Helper()
	lg := zaptest.NewLogger(t)
	ents := make([]raftpb.Entry, 0, len(requests))
	for i, request := range requests {
		ents = append(ents, raftpb.Entry{
			Term:  1,
			Index: uint64(i + 1),
			Type:  raftpb.EntryNormal,
			Data:  pbutil.MustMarshal(toInternalRaftRequest(request)),
		})
	}
	createMemberDataDir(t, dataDir)
	w, err := wal.Create(lg, datadir.ToWalDir(dataDir), nil)
	if err != nil {
		t.Fatalf("Failed to create WAL: %v", err)
	}
	st := raftpb.HardState{Term: 1, Commit: uint64(len(ents)), Vote: 1}
	if err := w.Save(st, ents); err != nil {
		t.Fatalf("Failed to save WAL: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Failed to close WAL: %v", err)
	}
}

func toInternalRaftRequest(request model.EtcdRequest) *pb.InternalRaftRequest {
	req := &pb.InternalRaftRequest{}
	switch request.Type {
	case model.Txn:
		txn := &pb.TxnRequest{}
		for _, cond := range request.Txn.Conds {
			txn.Compare = append(txn.Compare, &pb.Compare{
				Result:     pb.Compare_EQUAL,
				Target:     pb.Compare_VALUE,
				Key:        []byte(cond.Key),
				TargetUnion: &pb.Compare_Value{Value: []byte(cond.ExpectedValue.Value)},
			})
		}
		for _, op := range request.Txn.Ops {
			txn.Success = append(txn.Success, toRequestOp(op))
		}
		req.Txn = txn
	case model.LeaseGrant:
		req.LeaseGrant = &pb.LeaseGrantRequest{ID: request.LeaseGrant.LeaseID}
	case model.LeaseRevoke:
		req.LeaseRevoke = &pb.LeaseRevokeRequest{ID: request.LeaseRevoke.LeaseID}
	default:
		panic("unexpected request type")
	}
	return req
}

func toRequestOp(op model.EtcdOperation) *pb.RequestOp {
	switch op.Type {
	case model.Put:
		return &pb.RequestOp{
			Request: &pb.RequestOp_RequestPut{
				RequestPut: &pb.PutRequest{
					Key:   []byte(op.Key),
					Value: []byte(op.Value.Value),
					Lease: op.LeaseID,
				},
			},
		}
	case model.Delete:
		return &pb.RequestOp{
			Request: &pb.RequestOp_RequestDeleteRange{
				RequestDeleteRange: &pb.DeleteRangeRequest{Key: []byte(op.Key)},
			},
		}
	default:
		panic("unexpected operation type")
	}
}

