func TestDataReports(t *testing.T) {
	lg := zaptest.NewLogger(t)
	testdataPath := t.TempDir()
	// server-0 has a WAL with a single persisted put request.
	createMemberWAL(t, filepath.Join(testdataPath, "server-0"),
		model.EtcdRequest{
			Type: model.Txn,
			Txn: &model.TxnRequest{Ops: []model.EtcdOperation{{
				Type:  model.Put,
				Key:   "key",
				Value: model.ToValueOrHash("value"),
			}}},
		})
	// server-1 has no WAL, reading it should be tolerated as a minority failure.
	if err := os.MkdirAll(filepath.Join(testdataPath, "server-1"), 0755); err != nil {
		t.Fatal(err)
	}

	persistedRequests, err := report.LoadClusterPersistedRequests(lg, testdataPath)
	if err != nil {
		t.Fatalf("Failed to load persisted requests: %v", err)
	}
	if len(persistedRequests) != 1 {
		t.Fatalf("Unexpected number of persisted requests, got: %d, want: 1", len(persistedRequests))
	}

	baseTime := time.Now()
	history := model.NewAppendableHistory(identity.NewIdProvider())
	start := time.Since(baseTime)
	time.Sleep(time.Nanosecond)
	stop := time.Since(baseTime)
	// A failed put matching the persisted request should be kept in the history.
	history.AppendPut("key", "value", start, stop, nil, errors.New("failed"))

	visualize := ValidateAndReturnVisualize(t, lg, history.History.Operations(), nil, persistedRequests)
	visualize(filepath.Join(testdataPath, "history.html"))
}

// createMemberWAL creates a member data directory with a WAL containing the
// given requests.
func createMemberWAL(t *testing.T, dataDir string, requests ...model.EtcdRequest) {
	t.Helper()
	lg := zaptest.NewLogger(t)
	if err := os.MkdirAll(dataDir, 0755); err != nil {
		t.Fatal(err)
	}
	ents := make([]raftpb.Entry, 0, len(requests))
	for i, request := range requests {
		ents = append(ents, raftpb.Entry{
			Term:  1,
			Index: uint64(i + 1),
			Type:  raftpb.EntryNormal,
			Data:  pbutil.MustMarshal(toInternalRaftRequest(request)),
		})
	}
	w, err := wal.Create(lg, datadir.ToWalDir(dataDir), nil)
	if err != nil {
		t.Fatalf("Failed to create WAL: %v", err)
	}
	st := raftpb.HardState{Term: 1, Commit: uint64(len(ents)), Vote: 1}
	if err := w.Save(st, ents); err != nil {
		t.Fatalf("Failed to save WAL: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Failed to close WAL: %v", err)
	}
}

func toInternalRaftRequest(request model.EtcdRequest) *pb.InternalRaftRequest {
	req := &pb.InternalRaftRequest{}
	switch request.Type {
	case model.Txn:
		txn := &pb.TxnRequest{}
		for _, op := range request.Txn.Ops {
			txn.Success = append(txn.Success, toRequestOp(op))
		}
		req.Txn = txn
	default:
